// stashClick stashes the text, or opens the menu over an empty composer.
// Only the prompt travels; the attachments stay and the count says so.
func stashClick(key string) string {
	return "$prompt.trim() ? @post('/api/stash?key=" + key + "&att=' + $_attach.length, {filterSignals: {include: /^prompt$/}}) : ($pick = $pick == 'stash' ? '' : 'stash', $pick && @query('/api/stash?key=" + key + "'))"
}

