// idleWords is a rough "3 hours", "2 days".
func idleWords(d time.Duration) string {
	switch {
	case d < 2*time.Hour:
		return "an hour"
	case d < 48*time.Hour:
		return fmt.Sprintf("%d hours", int(d.Hours()))
	}
	return fmt.Sprintf("%d days", int(d.Hours()/24))
}

